{
  "name": "中央控制器（CC）",
  "name_en": "Central Controller (CC)",
  "manufacturer": "QuTech",
  "description": "一种用于超导量子比特实验的数字时序与序列控制设备，可加载并运行实验序列，协调 CCIO 模块与数字 I/O 链路，并支持状态监测、DIO 校准和时序延迟调整，常用于量子测控系统中的脉冲时序控制与实验同步。",
  "description_en": "A digital timing and sequence control instrument for superconducting qubit experiments. It loads and runs experiment sequences, coordinates CCIO modules and digital I/O links, and supports status monitoring, DIO calibration, and timing delay adjustment for pulse sequencing and experiment synchronization in quantum control setups.",
  "tag_hints": [
    "quantum experiment control",
    "superconducting qubits",
    "pulse sequence control",
    "digital timing synchronization",
    "DIO calibration",
    "CCIO modules",
    "SCPI instrument"
  ],
  "actions": [
    {
      "action_name": "auto-assemble",
      "description": "在控制器上汇编给定的序列程序。",
      "description_en": "Assemble a provided sequence program on the controller."
    },
    {
      "action_name": "auto-assemble_and_start",
      "description": "汇编给定的序列程序并启动控制器序列器。",
      "description_en": "Assemble a provided sequence program and start the controller sequencers."
    },
    {
      "action_name": "auto-calibrate_dio",
      "description": "校准指定 CCIO 的数字 I/O 链路。",
      "description_en": "Calibrate the digital I/O link of the specified CCIO."
    },
    {
      "action_name": "auto-debug_get_ccio_reg",
      "description": "读取指定 CCIO 的调试寄存器值。",
      "description_en": "Read the debug register value of the specified CCIO."
    },
    {
      "action_name": "auto-debug_get_ccio_trace",
      "description": "读取指定 CCIO 的调试跟踪数据。",
      "description_en": "Read debug trace data from the specified CCIO."
    },
    {
      "action_name": "auto-debug_get_traces",
      "description": "读取选定 CCIO 掩码的调试跟踪数据。",
      "description_en": "Read debug trace data for the selected CCIO mask."
    },
    {
      "action_name": "auto-debug_marker_in",
      "description": "将调试标记切换到指定输入位。",
      "description_en": "Route the debug marker to the specified input bit."
    },
    {
      "action_name": "auto-debug_marker_off",
      "description": "关闭调试标记输出。",
      "description_en": "Turn off the debug marker output."
    },
    {
      "action_name": "auto-debug_marker_out",
      "description": "将调试标记切换到指定输出位。",
      "description_en": "Route the debug marker to the specified output bit."
    },
    {
      "action_name": "auto-debug_set_ccio_trace_on",
      "description": "启用指定 CCIO 的调试跟踪。",
      "description_en": "Enable debug trace capture on the specified CCIO."
    },
    {
      "action_name": "auto-print_status_operation",
      "description": "显示控制器的组合运行状态。",
      "description_en": "Display the combined operation status of the controller."
    },
    {
      "action_name": "auto-print_status_questionable",
      "description": "显示控制器的组合可疑状态。",
      "description_en": "Display the combined questionable status of the controller."
    },
    {
      "action_name": "auto-sequence_program_assemble",
      "description": "设置待汇编的序列程序字符串。",
      "description_en": "Set the sequence program string to assemble."
    },
    {
      "action_name": "auto-set_q1_reg",
      "description": "设置指定 CCIO 的 Q1 寄存器值。",
      "description_en": "Set the Q1 register value for the specified CCIO."
    },
    {
      "action_name": "auto-set_seqbar_cnt",
      "description": "设置指定 CCIO 的序列屏障计数值。",
      "description_en": "Set the sequence barrier count for the specified CCIO."
    },
    {
      "action_name": "auto-set_status_operation_run_enable",
      "description": "设置运行状态报告使能。",
      "description_en": "Set operation run status reporting enable."
    },
    {
      "action_name": "auto-set_status_questionable_bplink_enable",
      "description": "设置背板链路可疑状态报告使能。",
      "description_en": "Set backplane link questionable status reporting enable."
    },
    {
      "action_name": "auto-set_status_questionable_config_enable",
      "description": "设置配置可疑状态报告使能。",
      "description_en": "Set configuration questionable status reporting enable."
    },
    {
      "action_name": "auto-set_status_questionable_frequency_enable",
      "description": "设置频率可疑状态报告使能。",
      "description_en": "Set frequency questionable status reporting enable."
    },
    {
      "action_name": "auto-set_status_questionable_instrument_enable",
      "description": "设置仪器可疑状态报告使能。",
      "description_en": "Set instrument questionable status reporting enable."
    },
    {
      "action_name": "auto-set_status_questionable_instrument_idetail_bplink_enable",
      "description": "设置指定 CCIO 的背板链路详细可疑状态报告使能。",
      "description_en": "Set detailed backplane link questionable status reporting enable for the specified CCIO."
    },
    {
