    {
      "action_name": "auto-set_vsm_delay_rise",
      "description": "设置指定 CCIO 位的 VSM 上升沿延迟。",
      "description_en": "Set VSM rising-edge delay for the specified CCIO bit."
    },
    {
      "action_name": "auto-start",
      "description": "启动控制器序列器。",
      "description_en": "Start the controller sequencers."
