    },
    {
      "action_name": "auto-stop",
      "description": "停止控制器序列器。",
      "description_en": "Stop the controller sequencers."
    },
    {
      "action_name": "auto-get_sequence_program_assemble",
      "description": "获取待汇编的序列程序字符串。",
      "description_en": "Get the sequence program string to assemble."
